#academyAnswer{background:#fff;border:1px solid #d9e0e4;border-radius:11px;padding:12px;font:inherit;color:#122638}#academyAnswer:focus{outline:2px solid #ff7955;outline-offset:1px}.journal-item{padding:13px 0;border-bottom:1px solid #e9edef}.journal-item:last-child{border-bottom:0}.journal-item p{white-space:pre-wrap;overflow-wrap:anywhere}.small-btn{font-size:12px;padding:6px 9px}.result{white-space:pre-wrap}#homeProgress .metric{min-width:0}
/* ABC BODY V18.3 · Kinetic Athletic visual system */
.legacy-weeks{display:none!important}
:root{--navy:#102638;--navy2:#153a4b;--coral:#ff7149;--mint:#88d4c5;--canvas:#f3f7f8;--shadow:0 10px 34px rgba(19,52,69,.065)}
body{background:var(--canvas);font-family:Inter,ui-sans-serif,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;letter-spacing:-.012em}
.shell{grid-template-columns:226px minmax(0,1fr)}.side{position:sticky;top:0;height:100vh;padding:29px 17px;gap:38px;background:linear-gradient(173deg,#102638,#0b2334)}.side .logo{font-size:27px;letter-spacing:-1.6px}.side .sub{font-size:9px;letter-spacing:2px}.side nav{display:grid;gap:6px}.nav{padding:13px 15px;border-radius:12px;font-size:13px;letter-spacing:0;font-weight:650}.nav.active{background:#254d5e;color:white;box-shadow:inset 3px 0 var(--mint)}.nav:hover{background:#244654}.side .note{border:1px solid #315063;background:#173b4a;color:#bed4da}.main{max-width:1570px;padding:34px clamp(20px,3.2vw,54px) 40px}.eyebrow{font-size:10px;letter-spacing:1.7px;color:#13837d}.card{border:1px solid #e0e9ec;box-shadow:var(--shadow);border-radius:17px}.btn{color:white;transition:transform .18s,filter .18s}.btn:hover{filter:brightness(.95);transform:translateY(-1px)}.btn.alt{color:#166b64}.bar{background:#dfe9eb;height:8px}.bar>span{background:linear-gradient(90deg,#5ccab0,#88d4c5)}
.dashboard-heading,.route-intro{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:24px}.dashboard-heading h1,.route-intro h1{font-size:clamp(27px,3.1vw,42px);font-weight:850;line-height:1.15;letter-spacing:-1.5px;margin:7px 0}.dashboard-heading p,.route-intro p{margin:0}.wave,.title-accent{color:var(--coral)}.avatar-action{display:flex;align-items:center;gap:10px;border:1px solid var(--line);background:white;padding:10px 15px;border-radius:13px;color:var(--navy);font-weight:750;box-shadow:var(--shadow)}.learning-hero{min-height:300px;border-radius:23px;background:radial-gradient(circle at 81% 25%,#255768 0%,transparent 40%),linear-gradient(112deg,#102638 24%,#153d4f 100%);padding:34px 40px;position:relative;isolation:isolate;overflow:hidden;color:white;display:flex;align-items:center;justify-content:space-between;gap:24px}.learning-hero:before{content:"";position:absolute;width:280px;height:430px;background:linear-gradient(140deg,transparent 45%,rgba(255,113,73,.95) 45%,rgba(255,113,73,.95) 60%,transparent 60%);right:20%;top:-100px;transform:rotate(-10deg);opacity:.7;z-index:-1}.hero-decoration{position:absolute;right:24%;top:-66px;font-size:340px;font-weight:900;opacity:.055;line-height:1;z-index:-1}.hero-content{max-width:550px;position:relative;z-index:1}.hero-kicker{color:#9adcd0;font-weight:850;font-size:11px;letter-spacing:1.4px}.hero-content h2{font-size:clamp(36px,4vw,56px);line-height:1.04;margin:17px 0 13px;font-weight:900;letter-spacing:-2px}.hero-content h2 em{color:#ff9476;font-style:normal}.hero-week{font-size:17px;font-weight:800;margin:0 0 5px}.hero-description{margin:0;color:#bfd1db;max-width:400px;font-size:13px}.hero-actions{display:flex;gap:11px;margin-top:24px;flex-wrap:wrap}.hero-btn{background:var(--coral);color:#fff;padding:13px 22px}.hero-outline{background:rgba(255,255,255,.08);color:#fff;border:1px solid #587080;border-radius:11px;padding:12px 17px;font-weight:750}.hero-progress{width:188px;flex-shrink:0;position:relative;z-index:1}.progress-ring{height:176px;width:176px;border-radius:50%;background:conic-gradient(var(--mint) calc(var(--progress)*1%),rgba(255,255,255,.16) 0);padding:13px;display:grid;place-items:center}.progress-ring>div{background:#173a49;width:100%;height:100%;border-radius:50%;display:flex;align-items:center;justify-content:center;flex-direction:column}.progress-ring strong{font-size:31px;line-height:1.3;letter-spacing:-1.1px}.progress-ring small{font-size:11px;color:#c7d9df}.dashboard-section-head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin:28px 0 13px}.dashboard-section-head h2{font-size:22px;line-height:1.2;letter-spacing:-.6px;margin:5px 0 0}.context-caption{color:#71848e;font-size:12px}.visual-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:13px}.visual-metric{border:1px solid #e1e9eb;background:#fff;border-radius:16px;box-shadow:var(--shadow);padding:18px;min-width:0}.visual-metric-top{display:flex;align-items:center;justify-content:space-between}.metric-icon{display:grid;place-items:center;background:#e7f4f1;color:#137e75;height:38px;width:38px;border-radius:11px;font-size:22px}.visual-metric strong{font-size:24px;letter-spacing:-.8px;display:block;margin-top:14px}.visual-metric h3{font-size:13px;font-weight:750;margin:2px 0 14px}.visual-metric .bar{height:7px}.metric-caption{font-size:11px;color:#68808a;margin-top:9px}.dashboard-bottom{display:grid;grid-template-columns:1.35fr 1fr;gap:15px;margin-top:16px}.next-lesson{display:flex;align-items:center;gap:17px;min-height:175px}.mini-icon{border-radius:14px;min-width:52px;height:52px;display:grid;place-items:center;font-size:29px}.coral-icon{color:#f76e4b;background:#fff0eb}.next-copy{flex:1;min-width:0}.next-copy h3,.cycle-overview h3{font-size:18px;margin:5px 0}.next-copy p,.cycle-overview p{color:#687f89;margin:0 0 9px;font-size:13px}.next-states{display:flex;gap:6px;flex-wrap:wrap}.state-chip{font-size:10px;font-weight:750;background:#eff4f5;border-radius:20px;padding:4px 8px;color:#637984}.state-chip.done{background:#e2f5ef;color:#147a67}.round-arrow{border:0;border-radius:50%;background:#ffefea;color:#e56a4b;font-size:25px;width:42px;height:42px;flex-shrink:0}.cycle-overview{border:1px solid #ccebe3;background:linear-gradient(120deg,#ecfaf7,#e1f5ef);border-radius:17px;padding:24px}.cycle-overview h3{margin:9px 0 6px}.cycle-overview .bar{margin:19px 0 6px}.method-details,.route-detail{border:1px solid var(--line);background:white;border-radius:15px;margin-top:19px;padding:15px 20px}.method-details summary,.route-detail summary{cursor:pointer;font-size:13px;font-weight:800;color:#294858;display:flex;justify-content:space-between}.method-details p{font-size:13px;color:#4f6874}.legacy-metrics{display:none}.route-intro{margin-bottom:19px}.route-count{background:#e5f5f1;color:#167b70;display:flex;align-items:center;gap:8px;border-radius:14px;padding:10px 16px}.route-count strong{font-size:28px}.route-count span{font-size:10px;letter-spacing:1.3px;font-weight:850}.route-filters{display:grid;grid-template-columns:1fr 1fr 1fr;gap:17px;align-items:center;padding:17px 19px;margin-bottom:25px}.route-filters label{margin:0 0 6px;font-size:11px}.route-filters select{height:44px;padding:9px 12px}.route-workspace{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(290px,.85fr);gap:20px;align-items:start}.cycle-stack .dashboard-section-head{margin:0 0 14px}.cycle-cards{display:grid;gap:12px}.cycle-card{background:white;border:1px solid #e1e9eb;border-radius:17px;padding:15px 16px;box-shadow:var(--shadow);transition:border-color .15s}.cycle-card.is-current{border:2px solid var(--coral);padding:14px 15px}.cycle-heading{display:flex;align-items:center;gap:13px}.cycle-icon{width:46px;height:46px;display:grid;place-items:center;background:#ebf8f4;border-radius:13px;color:#187d72;font-size:23px;flex-shrink:0}.cycle-card:nth-child(2) .cycle-icon{background:#ecf0fc;color:#647dc5}.cycle-card:nth-child(3) .cycle-icon{background:#f1f1fc;color:#7976b8}.cycle-card:nth-child(4) .cycle-icon{background:#fff4e6;color:#e5a643}.cycle-card h3{font-size:14px;margin:0 0 3px;line-height:1.3}.cycle-card p{font-size:11px;color:#6a7e87;margin:0}.cycle-badge{margin-left:auto;border-radius:20px;background:#eef2f3;color:#657883;padding:5px 10px;font-size:10px;font-weight:800;white-space:nowrap}.cycle-card.is-current .cycle-badge{background:#d8f5ec;color:#16766b}.cycle-weeks{display:grid;grid-template-columns:repeat(13,minmax(0,1fr));gap:4px;margin:13px 0 0 58px}.cycle-week{height:26px;border:0;border-radius:7px;font-size:10px;font-weight:750;color:#405765;background:#e9eff1;padding:0;min-width:0}.cycle-week.is-complete{background:#98e5c7;color:#07513f}.cycle-week.is-selected{background:var(--coral);color:white;box-shadow:0 2px 8px #ff71494d}.cycle-week:focus-visible{outline:2px solid var(--navy);outline-offset:1px}.route-legend{display:flex;justify-content:center;gap:18px;padding:14px 0;font-size:11px;color:#667b86;flex-wrap:wrap}.dot{display:inline-block;width:11px;height:11px;border-radius:4px;margin-right:4px;vertical-align:-1px}.dot-complete{background:#98e5c7}.dot-current{background:var(--coral)}.dot-upcoming{background:#dbe4e7}.selected-week{background:white;border:1px solid #e1e9eb;border-radius:19px;padding:21px;box-shadow:var(--shadow)}.selected-week-label{display:flex;align-items:center;justify-content:space-between;gap:9px;color:#6e8188;letter-spacing:1.4px;font-size:10px;font-weight:850}.selected-week-label span{background:#e7f4f1;color:#187b70;border-radius:20px;padding:5px 8px;letter-spacing:0}.selected-week-top{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-top:18px}.selected-week-top>span:first-child{font-weight:900;color:var(--coral);letter-spacing:1px;font-size:12px}.week-status{font-size:11px;font-weight:750;border-radius:14px;background:#eef2f3;padding:4px 9px;color:#667980}.week-status.done{background:#e1f6eb;color:#126f5c}.selected-week h2{font-size:25px;line-height:1.16;letter-spacing:-.7px;margin:10px 0 5px}.selected-week>.muted{font-size:12px;margin:0 0 12px}.week-visual{height:125px;background:linear-gradient(125deg,#153649,#266477);border-radius:13px;margin:14px 0 18px;position:relative;overflow:hidden;color:white;display:grid;place-items:center}.week-visual:after{content:'';position:absolute;width:200px;height:180px;transform:rotate(30deg);background:var(--coral);left:-130px;bottom:-80px}.week-visual-symbol{font-size:92px;opacity:.7;line-height:1}.week-visual-overlay{position:absolute;bottom:10px;right:12px;font-size:9px;letter-spacing:1.4px;font-weight:850;color:#c8e7e5}.selected-week>.eyebrow{display:block;margin-top:15px;color:#f27150}.selected-week>p:not(.muted){font-size:13px;line-height:1.55;margin:6px 0}.route-cta,.route-secondary-cta{display:block;width:100%;margin-top:13px}.route-secondary-cta{margin-top:8px}.route-detail{margin-top:20px}.route-detail>.grid{margin-top:15px!important}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap}
@media(max-width:1200px){.visual-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}.route-workspace{grid-template-columns:1fr}.cycle-weeks{gap:5px}.selected-week{max-width:none}.hero-progress{width:150px}.progress-ring{width:148px;height:148px}.route-filters{gap:10px}}
@media(max-width:920px){.shell{display:block}.side{position:relative;height:auto;display:block;padding:13px 15px}.side>div:first-child{display:flex;align-items:baseline;gap:12px}.side .sub,.side .note{display:none}.side nav{display:flex;overflow-x:auto;gap:6px;margin-top:10px;scrollbar-width:thin}.nav{min-width:max-content;padding:9px 13px}.main{padding:21px 16px 45px}.learning-hero{min-height:260px;padding:26px}.dashboard-heading h1{font-size:31px}.route-filters{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:650px){.dashboard-heading,.route-intro{align-items:start}.dashboard-heading h1,.route-intro h1{font-size:27px}.avatar-action span{display:none}.learning-hero{padding:24px;min-height:0;display:block}.hero-content h2{font-size:34px}.hero-progress{position:absolute;right:15px;top:15px;width:68px;opacity:.88}.progress-ring{width:64px;height:64px;padding:6px}.progress-ring strong{font-size:13px}.progress-ring small{display:none}.hero-content{padding-right:0}.hero-kicker{padding-right:65px;display:block}.hero-actions{margin-top:19px}.hero-description{max-width:245px}.visual-metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}.visual-metric{padding:13px}.visual-metric strong{font-size:21px}.visual-metric h3{font-size:12px}.dashboard-bottom{grid-template-columns:1fr}.next-lesson{padding:16px;min-height:0}.mini-icon{display:none}.dashboard-section-head{align-items:start}.context-caption{display:none}.route-count{padding:7px 10px}.route-count strong{font-size:23px}.route-filters{grid-template-columns:repeat(2,minmax(0,1fr));padding:13px}.route-cycle-field{grid-column:1/-1}.cycle-card{padding:13px}.cycle-card.is-current{padding:12px}.cycle-heading{gap:9px}.cycle-icon{width:38px;height:38px}.cycle-weeks{margin-left:0;grid-template-columns:repeat(7,minmax(0,1fr));gap:6px}.cycle-week{height:32px;font-size:11px}.cycle-badge{font-size:9px;padding:4px 7px}.route-legend{gap:9px}.selected-week{padding:17px}.route-detail>.grid{grid-template-columns:1fr}}
</style></head><body><div class="shell"><aside class="side"><div><div class="logo">ABC<em>HUMAN</em></div><div class="sub">THE HUMAN DEVELOPMENT PLATFORM</div></div><nav id="nav"><button class="nav active" data-view="inicio">⌂ Inicio</button><button class="nav" data-view="perfil">◉ Perfil</button><button class="nav" data-view="ruta">▦ Ruta Anual</button><button class="nav" data-view="academia">◧ Academia</button><button class="nav" data-view="evidencia">▶ Entrena</button><button class="nav" data-view="trayectoria">↗ Mi Trayectoria</button><button class="nav" data-view="medallero">🏅 Medallero</button></nav><div class="note">MODO LOCAL · Sin Supabase ni inicio de sesión. Guarda respaldos regularmente. Currículo en revisión académica.</div></aside><main class="main"><div class="view active" id="inicio">
<div class="dashboard-heading"><div><span class="eyebrow">TU ESPACIO DE APRENDIZAJE</span><h1>Hola, <span id="visualName">estudiante</span><span class="wave"> ✦</span></h1><p class="muted" id="visualProfile">Tu progreso empieza aquí.</p></div><button class="avatar-action" onclick="show('perfil')" aria-label="Editar mi perfil">◉ <span>Mi perfil</span></button></div>
<div class="learning-hero"><div class="hero-content"><span class="hero-kicker">✦ TU PLAN ANUAL · <span id="heroProgram">ABC KIDS</span></span><h2>Continúa tu<br><em>aprendizaje.</em></h2><p class="hero-week" id="heroWeek">Semana 01 · Ciclo 1</p><p class="hero-description" id="heroDescription">Tu siguiente actividad está lista para explorar.</p><div class="hero-actions"><button class="btn hero-btn" onclick="show('academia')">▶ Continuar lección</button><button class="hero-outline" onclick="show('ruta')">Ver mi ruta ↗</button></div></div><div class="hero-progress"><div class="progress-ring" id="heroRing" style="--progress:0"><div><strong id="heroRingValue">0/13</strong><small>semanas del ciclo</small></div></div></div><div class="hero-decoration" aria-hidden="true">↗</div></div>
<div class="dashboard-section-head"><div><span class="eyebrow">MI PROGRESO</span><h2>Aprendizaje en movimiento</h2></div><span class="context-caption">Se actualiza con tus registros locales</span></div><div id="visualMetrics" class="visual-metrics"></div>
<div class="dashboard-bottom"><div class="next-lesson card"><div class="mini-icon coral-icon">◎</div><div class="next-copy"><span class="eyebrow">TU SIGUIENTE PASO</span><h3 id="nextTitle">Próxima actividad</h3><p id="nextDescription">Tu plan de aprendizaje personalizado</p><div class="next-states" id="nextStates"></div></div><button class="round-arrow" onclick="show('ruta')" aria-label="Ver semana actual">→</button></div><div class="cycle-overview"><span class="eyebrow">CICLO ACTUAL</span><h3 id="cycleOverviewTitle">Ciclo 1 · Semanas 1–13</h3><p id="cycleOverviewDescription">Explora los fundamentos de esta etapa</p><div class="bar"><span id="cycleOverviewBar" style="width:0%"></span></div><span id="cycleOverviewCount" class="small muted">0 de 13 semanas</span></div></div>
<details class="method-details"><summary>Cómo funciona la adaptación <span aria-hidden="true">＋</span></summary><p>La edad determina una ruta de referencia. El estado de cada dominio recomienda una variante base, progresión o desafío. Las observaciones manuales y las validaciones docentes se identifican por separado; ninguna acción concede una certificación automática.</p><p class="warn">Modo local de desarrollo. Guarda respaldos en Perfil. Evita incluir información personal identificable o videos reales de menores.</p><div id="homeProgress" class="legacy-metrics" aria-hidden="true"></div><span id="summaryName" hidden></span><span id="summaryAge" hidden></span><span id="summaryTrack" hidden></span><span id="summaryLesson" hidden></span><span id="summaryReason" hidden></span></details>
</div><div class="view" id="perfil"><div class="card"><div class="eyebrow">ABC BODY / PERFIL LOCAL</div><h2>Mi perfil de aprendizaje</h2><p class="muted">Perfil único de desarrollo local. No se sincroniza entre dispositivos.</p><div class="grid"><div><label>Alias (no nombre real)</label><input id="alias" type="text" maxlength="36" placeholder="Estudiante demo"><label>Fecha de nacimiento (simulada)</label><input id="dob" type="date"><label>Edad curricular de referencia</label><select id="age"></select></div><div><label>Programa</label><select id="program"><option value="KIDS">ABC KIDS</option><option value="YOUTH">ABC YOUTH</option><option value="ATHLETE">ABC ATHLETE</option><option value="ACTIVE">ABC ACTIVE</option><option value="LONGEVITY">ABC LONGEVITY</option></select></div><div><label>Experiencia</label><select id="experience"><option value="nuevo">Comenzando</option><option value="regular">Practica con regularidad</option><option value="deportista">Participa en deporte organizado</option></select><label>Ajustes de accesibilidad</label><select id="supports"><option value="estandar">Sin ajustes registrados</option><option value="apoyos">Con apoyo o materiales adaptados</option><option value="supervision">Requiere revisión individual del instructor</option></select><label>Carga de actividad externa</label><select id="load"><option value="baja">Baja o no especificada</option><option value="media">Moderada</option><option value="alta">Alta (deporte frecuente)</option></select></div></div><div class="line"><button class="btn" id="saveProfile">Guardar perfil de prueba</button></div><p class="small muted">La fecha de nacimiento no se utiliza para afirmar maduración biológica; la edad curricular puede ajustarse con acompañamiento profesional.</p></div><div class="card" style="margin-top:18px" id="localStoragePanel"><div class="eyebrow">ABC BODY / MIS DATOS</div><h2>Almacenamiento en este dispositivo</h2><p class="muted">Un solo perfil de desarrollo. El progreso se conserva en localStorage; los videos, en IndexedDB. No existe conexión a Supabase. Si borras datos del navegador, se perderán salvo que hagas un respaldo.</p><div class="line" style="display:flex;flex-wrap:wrap;gap:10px"><button class="btn" id="exportBackup">Descargar respaldo JSON</button><button class="btn alt" id="importBackup">Restaurar respaldo JSON</button><input id="backupFile" type="file" accept=".json,application/json" hidden><button class="btn alt" id="exportMedia">Exportar videos por separado</button></div><p class="small muted" id="storageMessage">Los respaldos JSON incluyen perfil y progreso, no los archivos de video. Guarda tus videos descargados por separado.</p><p class="small muted">No cambies el nombre de la carpeta o la URL local sin hacer un respaldo: algunos navegadores separan el almacenamiento por origen.</p></div></div><div class="view" id="ruta"><div class="route-intro"><div><span class="eyebrow">ABC BODY · MI PLAN PERSONALIZADO</span><h1>Ruta anual <span class="title-accent">✦</span></h1><p class="muted">52 semanas, 4 ciclos de aprendizaje. Avanza a tu ritmo.</p></div><div class="route-count"><strong>52</strong><span>SEMANAS</span></div></div>
<div class="route-filters card"><div class="route-field"><label for="routeProgram">Programa</label><select id="routeProgram"><option value="KIDS">ABC KIDS</option><option value="YOUTH">ABC YOUTH</option><option value="ATHLETE">ABC ATHLETE</option><option value="ACTIVE">ABC ACTIVE</option><option value="LONGEVITY">ABC LONGEVITY</option></select></div><div class="route-field"><label for="routeAge">Edad curricular</label><select id="routeAge"></select></div><div class="route-field route-cycle-field"><label for="cycle">Ir al ciclo</label><select id="cycle"><option value="1">Ciclo 1 · Semanas 1–13</option><option value="2">Ciclo 2 · Semanas 14–26</option><option value="3">Ciclo 3 · Semanas 27–39</option><option value="4">Ciclo 4 · Semanas 40–52</option></select></div><span id="routeHeading" class="sr-only">Ruta anual</span><span id="cycleTag" class="sr-only"></span></div>
<div class="route-workspace"><div class="cycle-stack"><div class="dashboard-section-head"><div><span class="eyebrow">TU RECORRIDO</span><h2>Los cuatro ciclos</h2></div><span class="context-caption">Selecciona cualquier semana</span></div><div id="cycleCards" class="cycle-cards"></div><div id="weeks" class="weeks legacy-weeks" hidden></div><div class="route-legend"><span><i class="dot dot-complete"></i> Practicada</span><span><i class="dot dot-current"></i> Seleccionada</span><span><i class="dot dot-upcoming"></i> Por explorar</span></div></div><div class="selected-week"><div class="selected-week-label">ACTIVIDAD SELECCIONADA <span id="selectedCycleBadge">CICLO 1</span></div><div class="selected-week-top"><span id="selectedWeekNumber">SEMANA 01</span><span class="week-status" id="selectedWeekStatus">Por explorar</span></div><h2 id="selectedWeekTitle">Actividad de la semana</h2><p class="muted" id="selectedWeekDomain">Aprende y progresa paso a paso</p><div class="week-visual" aria-hidden="true"><div class="week-visual-symbol">✦</div><div class="week-visual-overlay">APRENDE · PRACTICA · EVOLUCIONA</div></div><span class="eyebrow">OBJETIVO</span><p id="selectedWeekObjective">El objetivo de aprendizaje aparecerá aquí.</p><span class="eyebrow">PRÁCTICA</span><p id="selectedWeekPractice">Revisa la actividad y sus indicaciones.</p><button class="btn route-cta" onclick="show('academia')">▶ Ver lección completa</button><button class="btn alt route-secondary-cta" onclick="show('evidencia')">Ir a practicar ↗</button></div></div>
<details class="route-detail"><summary>Ver contenido completo y evaluación de la semana <span aria-hidden="true">＋</span></summary>
